                        icon={option.icon}
                        label={option.label}
                        onClick={() => {
                          setSystemDraft((current) => ({ ...current, theme_mode: option.key }));
                          patchPreference({ themeMode: option.key });
                          saveSystemMutation.mutate({ theme_mode: option.key });
