                      <ChoicePill
                        key={option.key}
                        active={systemDraft.language === option.key}
                        icon={<Globe size={16} />}
                        label={option.label}
                        onClick={() => {
                          setSystemDraft((current) => ({ ...current, language: option.key }));
                          patchPreference({ language: option.key });
                          saveSystemMutation.mutate({ language: option.key });
                        }}
                      />
